/* WEBSITE CHAT · MY APPOINTMENTS (workflow 18)
   The website's chat window asks this workflow, through the website's own
   server and the DentalFlow web key, for a visitor's upcoming appointments
   ("list") or to cancel one of them ("cancel").

   The visitor proves nothing but the mobile number or email they booked
   with. Set MATCH to 'both' to require the mobile number AND the email of
   the same booking (the chat then asks for both in one message).          */

/* ==========================================================================
   >>> EDIT THESE <<<
   ========================================================================== */
const SHEET_ID            = 'PASTE_YOUR_GOOGLE_SHEET_ID';
const CLINIC_NAME         = 'Smile Dental Clinic';
const CLINIC_PHONE        = '+92 300 000 0000';
const CLINIC_WHATSAPP     = '';               // digits only with country code, e.g. 923001234567 ('' = none)
const CALENDAR_ID         = 'primary';        // used for bookings made before there were several dentists
const TIMEZONE            = 'Asia/Karachi';
const CANCEL_CUTOFF_HOURS = 0;                // 0 = can cancel any time before the visit starts
const MATCH               = 'either';         // 'either' = mobile OR email; 'both' = mobile AND email of the same booking
const EMAIL_PATIENT       = true;             // email the patient when a booking is cancelled from the website
const MAX_SHOWN           = 10;               // at most this many appointments are listed
/* ========================================================================== */
const PHONE_MATCH_DIGITS = 10;                // a number is matched on its last 10 digits

const b = ($input.first().json || {}).body || {};
const clean = v => String(v ?? '').replace(/[\r\n\t]+/g, ' ').trim();
const action = b.action === 'cancel' ? 'cancel' : 'list';
const lang = ['en', 'ur', 'ar'].includes(clean(b.lang)) ? clean(b.lang) : 'en';

const digits = clean(b.phone).replace(/\D/g, '');
const phoneKey = digits.length >= PHONE_MATCH_DIGITS && digits.length <= 15 ? digits.slice(-PHONE_MATCH_DIGITS) : '';
const emailRaw = clean(b.email).toLowerCase().slice(0, 120);
const email = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(emailRaw) ? emailRaw : '';
const reference = clean(b.reference).toUpperCase().replace(/\s+/g, '').slice(0, 20);

let invalid = '';
if (MATCH === 'both' ? !(phoneKey && email) : !(phoneKey || email)) invalid = MATCH === 'both' ? 'need-phone-and-email' : 'invalid-contact';
else if (action === 'cancel' && !/^DN-?[A-Z0-9]{3,12}$/.test(reference)) invalid = 'invalid-reference';

return [{ json: { SHEET_ID, CLINIC_NAME, CLINIC_PHONE, CLINIC_WHATSAPP, CALENDAR_ID, TIMEZONE,
  CANCEL_CUTOFF_HOURS, MATCH, EMAIL_PATIENT, MAX_SHOWN, PHONE_MATCH_DIGITS,
  action, lang, phoneKey, email, reference, invalid } }];

/* The visitor's own bookings, from the Appointments tab.
   Appointments columns: A reference · C status · E treatment · F date · G time
   H minutes · I name · J phone · K email · L notes · M calendar event · T dentist · U calendar.
   "list":   upcoming PENDING / CONFIRMED bookings of this mobile number or email.
   "cancel": checks the reference is one of THEIR bookings and can still be
             cancelled, then hands it on to free the dentist's calendar slot.
   A reference that is not theirs gets the same answer as one that does not
   exist, so nobody learns whether a reference exists.                       */
const c = $('Config').first().json;
const res = $input.first().json || {};
const done = response => [{ json: { ...c, go: false, response } }];

if (c.invalid) return done({ ok: false, reason: c.invalid });
if (!Array.isArray(res.values) && res.error) return done({ ok: false, reason: 'sheet-error' });
const rows = Array.isArray(res.values) ? res.values : [];

const tail = s => String(s || '').replace(/\D/g, '').slice(-c.PHONE_MATCH_DIGITS);
const low = s => String(s || '').trim().toLowerCase();
const refKey = s => String(s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const mine = r => {
  const p = !!c.phoneKey && tail(r[9]).length === c.PHONE_MATCH_DIGITS && tail(r[9]) === c.phoneKey;
  const e = !!c.email && low(r[10]) === c.email;
  return c.MATCH === 'both' ? p && e : p || e;
};

// the clinic's UTC offset, e.g. +05:00, so "2026-10-15 10:30" is read as clinic time
const off = (() => {
  try {
    const s = new Intl.DateTimeFormat('en-US', { timeZone: c.TIMEZONE, timeZoneName: 'longOffset' })
      .formatToParts(new Date()).find(x => x.type === 'timeZoneName').value.replace('GMT', '');
    return s || '+00:00';
  } catch (e) { return '+00:00'; }
})();
const hhmm = t => { const m = /^(\d{1,2}):(\d{2})/.exec(String(t || '').trim()); return m ? `${m[1].padStart(2, '0')}:${m[2]}` : ''; };
const startOf = r => Date.parse(`${String(r[5] || '').trim()}T${hhmm(r[6]) || '00:00'}:00${off}`);
const ACTIVE = ['PENDING', 'CONFIRMED'];
const now = Date.now();

const card = r => ({
  reference: String(r[0] || '').trim(),
  service: String(r[4] || '').trim(),
  dentist: String(r[19] || '').trim(),
  date: String(r[5] || '').trim(),
  time: hhmm(r[6]),
  minutes: Number(r[7]) || 30,
  status: String(r[2] || '').trim().toUpperCase() === 'PENDING' ? 'pending' : 'confirmed',
});

if (c.action === 'list') {
  const list = rows
    .map((r, i) => ({ r, i, at: startOf(r) }))
    .filter(x => mine(x.r) && ACTIVE.includes(String(x.r[2] || '').trim().toUpperCase()) && Number.isFinite(x.at) && x.at > now)
    .sort((a, b) => a.at - b.at)
    .slice(0, c.MAX_SHOWN)
    .map(x => card(x.r));
  return done({ ok: true, appointments: list, cutoffHours: Number(c.CANCEL_CUTOFF_HOURS) || 0 });
}

/* ---- cancel ------------------------------------------------------------- */
const idx = rows.findIndex(r => refKey(r[0]) === refKey(c.reference) && mine(r));
if (idx < 0) return done({ ok: false, reason: 'not-found', reference: c.reference });
const r = rows[idx];
const status = String(r[2] || '').trim().toUpperCase();
if (status === 'CANCELLED') return done({ ok: false, reason: 'already-cancelled', reference: r[0] });
if (!ACTIVE.includes(status)) return done({ ok: false, reason: 'not-active', reference: r[0] });
const at = startOf(r);
const hrs = (at - now) / 3600000;
if (!Number.isFinite(at) || hrs <= 0) return done({ ok: false, reason: 'past', reference: r[0] });
if (hrs < Number(c.CANCEL_CUTOFF_HOURS)) return done({ ok: false, reason: 'too-late', reference: r[0], cutoffHours: Number(c.CANCEL_CUTOFF_HOURS) });

// a row without a calendar event (typed in by hand): Google answers 404, which counts as "already free"
const eventId = String(r[12] || '').trim() || '__no-event__';
const prettyDate = d => new Date(d + 'T12:00:00Z').toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
const pretty12 = t => { const [h, m] = (hhmm(t) || '00:00').split(':').map(Number); return `${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${h >= 12 ? 'PM' : 'AM'}`; };
const stamp = new Date().toLocaleString('en-GB', { timeZone: c.TIMEZONE });
const notes = String(r[11] || '').trim();
return [{ json: { ...c, go: true, rowNumber: idx + 2,
  appt: { ...card(r), name: String(r[8] || '').trim(), email: String(r[10] || '').trim(), eventId,
    calendarId: String(r[20] || '').trim() || c.CALENDAR_ID, when: `${prettyDate(String(r[5]).trim())} at ${pretty12(r[6])}` },
  note: `${notes}${notes ? ' | ' : ''}Cancelled by patient in the website chat ${stamp}` } }];

/* Google's answer to "delete this event":
     2xx      -> deleted: the dentist's time is free again
     404/410  -> it was already gone: the same end state, so it counts as success
     anything else (401/403 = credential, 5xx = Google) -> the time is still
              blocked, so the booking is NOT marked cancelled: the sheet must
              never say CANCELLED while the calendar keeps the chair booked.   */
const v = $('Find').first().json;
const code = Number(($input.first().json || {}).statusCode || 0);
if ((code >= 200 && code < 300) || code === 404 || code === 410) return [{ json: { ...v, freed: true, alreadyGone: code === 404 || code === 410 } }];
return [{ json: { ...v, freed: false, response: { ok: false, reason: 'calendar-error', reference: v.appt.reference } } }];

/* The answer for the chat window, and the cancellation email for the patient. */
const v = $('Released?').first().json;
const a = v.appt;
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const sendEmail = v.EMAIL_PATIENT === true && /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(a.email);
const waDigits = String(v.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const waBook = waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent('I would like to book an appointment.')}` : '';
const email = `
<div style="font-family:Helvetica,Arial,sans-serif;max-width:520px;margin:0 auto;color:#16272F">
  <div style="border-left:3px solid #B91C1C;padding:14px 18px;background:#FEF2F2;border-radius:0 8px 8px 0">
    <p style="margin:0;font-size:15px"><strong>Your appointment has been cancelled.</strong></p>
  </div>
  <p style="font-size:15px;line-height:1.6">Hello ${esc(a.name) || 'there'},</p>
  <p style="font-size:15px;line-height:1.6">The appointment below was cancelled in the chat on our website. The time is now free for another patient.</p>
  <table style="font-size:15px;line-height:1.9;border-collapse:collapse;margin:18px 0">
    <tr><td style="color:#566B75;padding-right:18px">Reference</td><td><strong>${esc(a.reference)}</strong></td></tr>
    <tr><td style="color:#566B75;padding-right:18px">Treatment</td><td>${esc(a.service)}</td></tr>
    ${a.dentist ? `<tr><td style="color:#566B75;padding-right:18px">Dentist</td><td>${esc(a.dentist)}</td></tr>` : ''}
    <tr><td style="color:#566B75;padding-right:18px">Was booked for</td><td>${esc(a.when)}</td></tr>
  </table>
  ${waBook ? `<p style="font-size:15px;line-height:1.6">Changed your mind? <a href="${waBook}" style="color:#0E7490">Book another time on WhatsApp</a>, or in the chat on our website.</p>` : '<p style="font-size:15px;line-height:1.6">Changed your mind? You can book another time in the chat on our website.</p>'}
  <p style="font-size:13px;color:#566B75;line-height:1.6">${esc(v.CLINIC_NAME)} &middot; ${esc(v.CLINIC_PHONE)}<br>
    If you did not cancel this yourself, please phone us straight away.</p>
</div>`;
return [{ json: { ...v, sendEmail, subject: `Cancelled: ${a.service} on ${a.when} (${a.reference})`, email,
  response: { ok: true, reference: a.reference, status: 'cancelled', emailed: sendEmail } } }];
